export function migrateId(id){return Object.hasOwn(OLD_IDS,id)?OLD_IDS[id]:id}
/* 舊存檔：集章、行程目的地改成新編號（同一地點有兩個舊章時保留較早的日期） */
export function migrateSave(raw){
  if(!raw||typeof raw!=='object')return raw;
  const out={...raw};
  if(raw.stamps&&typeof raw.stamps==='object'){const s={};for(const [k,v] of Object.entries(raw.stamps)){const id=migrateId(k);if(!s[id]||String(v)<String(s[id]))s[id]=v}out.stamps=s}
  const meta=m=>m&&typeof m==='object'&&m.recordId?{...m,recordId:migrateId(m.recordId)}:m;
  if(raw.journey&&typeof raw.journey==='object')out.journey={...raw.journey,meta:meta(raw.journey.meta),pending:raw.journey.pending?{...raw.journey.pending,meta:meta(raw.journey.pending.meta)}:raw.journey.pending};
  return out;
}
